import { useMemo } from 'react';

import { TableDataType } from 'components/Table/types';
import { useBffData } from 'hooks';
import { FilterOption } from 'models/Filters';

import { BFF_VIEW_ID } from '../constants';

export interface InvestmentBreakdownData {
  investment_breakdown?: TableDataType;
  filter?: FilterOption[];
}

export function useKpiRequests() {
  const bffResult = useBffData({
    id: BFF_VIEW_ID,
    kpiGroup: 'media',
  });

  const data = useMemo<InvestmentBreakdownData>(() => {
    const componentData = bffResult.data?.investment_breakdown;
    const tableData = componentData?.investment_breakdown;

    if (!tableData) {
      return { investment_breakdown: undefined };
    }

    return {
      investment_breakdown: tableData,
      filter: componentData?.filter,
    };
  }, [bffResult.data]);

  return {
    data,
    loading: bffResult.loading,
    error: bffResult.error,
  };
}
